#include <stdio.h>

int main() {
    FILE *fp = fopen("data.txt", "w");
    fprintf(fp, "Reading files in C is straightforward");
    fclose(fp);

    char buffer[100];
    fp = fopen("data.txt", "r");
    fgets(buffer, sizeof(buffer), fp);
    fclose(fp);

    printf("Read: %s\n", buffer);
    return 0;
}
